DO $post$
DECLARE n integer;
BEGIN
  SELECT count(*) INTO n FROM inform.politician_context
   WHERE season_id = '86d893a1-c1a2-4bbf-b4e5-69ec43221194' AND reasoning LIKE '%(migration 1906)%';
  IF n <> 21 THEN
    RAISE EXCEPTION 'migration 1906: expected 21 rows written, found %', n;
  END IF;
  -- the five awaiting a decision must still be 0, and nothing else written here may be
  SELECT count(*) INTO n FROM inform.politician_context c
    JOIN inform.politician_answers a ON a.politician_id = c.politician_id
     AND a.topic_id = c.topic_id AND a.season_id = c.season_id
   WHERE c.season_id = '86d893a1-c1a2-4bbf-b4e5-69ec43221194' AND c.reasoning LIKE '%(migration 1906)%' AND a.value = 0;
  IF n <> 5 THEN
    RAISE EXCEPTION 'migration 1906: expected exactly 5 rows left at 0, found %', n;
  END IF;
END
$post$;
